```c
static void walChecksumBytes(
  int nativeCksum, /* True for native byte-order, false for non-native */
  u8 *a,           /* Content to be checksummed */
  int nByte,       /* Bytes of content in a[].  Must be a multiple of 8. */
  const u32 *aIn,  /* Initial value */
  u32 *aOut        /* OUT: Final value */
){
  u32 s1, s2;
  u32 *aData = (u32 *)a;
  u32 *aEnd = (u32 *)&a[nByte];

  if( aIn ){
    s1 = aIn[0];
    s2 = aIn[1];
  }else{
    s1 = s2 = 0;
  }

  if( nativeCksum ){
    do {
      s1 += *aData++ + s2;
      s2 += *aData++ + s1;
    }while( aData<aEnd );
  }else{
    do {
      s1 += BYTESWAP32(*aData++) + s2;
      s2 += BYTESWAP32(*aData++) + s1;
    }while( aData<aEnd );
  }

  aOut[0] = s1;
  aOut[1] = s2;
}
```

So per 8-byte chunk: s1 += x0 + s2; s2 += x1 + s1. Here x0, x1 are 32-bit words (byteswapped in the case where magic is 0x377f0682, i.e., little-endian storage — non-native on a big-endian reference implementation... the magic bit indicates whether the checksum is stored in byte-swapped form). My loop: s0 += a + s1; s1 = (s1 + b + s0) — matches (s0 is s1, s1 is s2).

